import{_ as e,C as n,o as s,c as a,j as d,a as o,E as g,a2 as c}from"./chunks/framework.CnHmQiA8.js";const u=JSON.parse('{"title":"常见问题与主题设置","description":"","frontmatter":{"title":"常见问题与主题设置","outline":[2,3]},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1795529054000}'),l={name:"guide/faq.md"};function i(h,t,_,p,f,b){const r=n("TutorialVideo");return s(),a("div",null,[t[0]||(t[0]=d("h1",{id:"常见问题与主题设置",tabindex:"-1"},[o("常见问题与主题设置 "),d("a",{class:"header-anchor",href:"#常见问题与主题设置","aria-label":'Permalink to "常见问题与主题设置"'},"​")],-1)),t[1]||(t[1]=d("h2",{id:"_1-软件设置与配色主题",tabindex:"-1"},[o("1. 软件设置与配色主题 "),d("a",{class:"header-anchor",href:"#_1-软件设置与配色主题","aria-label":'Permalink to "1. 软件设置与配色主题"'},"​")],-1)),g(r,{id:"themes-settings"}),t[2]||(t[2]=c('<p>在首页左侧栏点击 <strong>设置…</strong>，可配置 <strong>教学案库位置</strong>、<strong>导入默认格式预设</strong>、<strong>公式字母默认正斜体</strong>、<strong>默认导出知识点重点难点汇总</strong>、<strong>连接 WorkBuddy</strong> 以及 <strong>配色主题</strong>（预览 A4 纸面与导出 Word 始终保持白纸黑字，不受主题影响）：</p><table tabindex="0"><thead><tr><th>主题名称</th><th>类型</th><th>视觉风格说明</th></tr></thead><tbody><tr><td><strong>青灰</strong>（默认）</td><td>常规</td><td>安静的青灰工作台，配“批改红”强调色</td></tr><tr><td><strong>暖纸</strong> / <strong>雾蓝</strong> / <strong>素白</strong> / <strong>深色</strong></td><td>常规</td><td>分别提供米色纸面、冷调蓝灰、中性素白与暗色面板</td></tr><tr><td><strong>赤黑</strong></td><td>风格主题</td><td>红黑白高反差、剪报拼贴标题、游移四边形悬停、斜幕切页与右键“战斗指令”式菜单</td></tr><tr><td><strong>月潮</strong></td><td>风格主题</td><td>深海蓝与青色辉光、逐字浮起标题、流光按钮与三层海水切页过场</td></tr></tbody></table><p>选择“赤黑”或“月潮”后，下方可逐项开关动效；系统开启“减弱动态效果”时动画自动关闭。</p><h2 id="_2-常用快捷键速查" tabindex="-1">2. 常用快捷键速查 <a class="header-anchor" href="#_2-常用快捷键速查" aria-label="Permalink to &quot;2. 常用快捷键速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><strong>首页文件列表</strong></td><td><code>Enter</code> / <code>F2</code> / <code>Delete</code></td><td>打开 / 重命名（同步 <code>.tplan</code> 文件名） / 删除到回收站</td></tr><tr><td><strong>标签页管理</strong></td><td><code>Ctrl+Tab</code> / <code>Ctrl+W</code></td><td>切换标签页 / 关闭当前标签页（鼠标中键也可关闭）</td></tr><tr><td><strong>编辑界面</strong></td><td><code>Ctrl+E</code></td><td>打开导出 Word 对话框</td></tr><tr><td><strong>编辑界面</strong></td><td><code>Ctrl+Z</code> / <code>Ctrl+Y</code>（<code>Ctrl+Shift+Z</code>）</td><td>撤销 / 重做（最多 200 步）</td></tr><tr><td><strong>文字格式</strong></td><td><code>Ctrl+B</code> / <code>Ctrl+I</code> / <code>Ctrl+U</code></td><td>加粗 / 倾斜 / 下划线</td></tr><tr><td><strong>图片与表格</strong></td><td><code>Shift + 拖动</code> / <code>Shift + 单击</code></td><td>全部选项图一起缩放 / 连选多个单元格合并</td></tr><tr><td><strong>大纲排序</strong></td><td><code>Esc</code></td><td>取消当前拖拽排序</td></tr></tbody></table><h2 id="_3-常见问题" tabindex="-1">3. 常见问题 <a class="header-anchor" href="#_3-常见问题" aria-label="Permalink to &quot;3. 常见问题&quot;">​</a></h2><ul><li><strong>导出的 Word 其他老师能直接改吗？</strong> 可以。导出为标准 <code>.docx</code>，题号与 <code>【答案】</code> 为 Word 自动编号，公式和表格为 Word 原生格式，无需安装本软件即可在 Word / WPS 中继续编辑。</li><li><strong><code>.tplan</code> 工程怎么备份或发给同事？</strong><code>.tplan</code> 是单文件工程（内置题目、公式与全部插图），直接复制 <code>.tplan</code> 文件或备份整个教学案库目录即可。</li><li><strong>安装后首次打开被系统拦截？</strong> Windows 遇 SmartScreen 提示点 <strong>更多信息 → 仍要运行</strong>；macOS 遇提示请打开 <strong>系统设置 → 隐私与安全性 → 仍要打开</strong>，详见 <a href="/Teaching-plan-production/download.html#安装注意事项">下载安装说明</a>。</li><li><strong>墨案导入登录卡住或失败？</strong> 在墨案窗口 <strong>页面</strong> 菜单尝试 <strong>强制刷新（忽略缓存）</strong> 或 <strong>清除登录状态与缓存并刷新</strong>；若导入异常，点 <strong>导入 → 保存诊断文件</strong>（已隐去登录凭证）以便排查。</li></ul>',7))])}const C=e(l,[["render",i]]);export{u as __pageData,C as default};
